/**
 * (#7274) Externref-ABI adapters over the native `ArrayBuffer` providers, the
 * backend half of `ir/native-buffer-surface.ts`.
 *
 * The IR carries a native buffer as `extern<ArrayBuffer>` — physically the
 * externref legacy stores in a script var's `__mod_` slot — and calls one
 * adapter per certified operation. Each adapter is a plain function whose body
 * is generated by the SAME emitter legacy inlines at its source site
 * (`array-buffer-native.ts`, `emitArrayBufferSliceParamsBody`), with the
 * operands read from params, so there is one implementation of each sequence.
 *
 *   __ir_ab_new(f64)                          -> externref
 *   __ir_ab_new_resizable(f64, f64)           -> externref
 *   __ir_ab_byte_length(externref)            -> f64
 *   __ir_ab_max_byte_length(externref)        -> f64
 *   __ir_ab_resizable(externref)              -> i32 (boolean)
 *   __ir_ab_slice(externref, externref, externref) -> externref
 *
 * The slice bounds are the IR's dynamic carrier, which is the externref
 * legacy's slice ToNumber reads only off fast mode, hence the availability
 * predicate below.
 */
import type { FuncHandle, ValType } from "../../ir/types.js";
import {
  IR_NATIVE_AB_BYTE_LENGTH_FN,
  IR_NATIVE_AB_MAX_BYTE_LENGTH_FN,
  IR_NATIVE_AB_NEW_FN,
  IR_NATIVE_AB_NEW_RESIZABLE_FN,
  IR_NATIVE_AB_RESIZABLE_FN,
  IR_NATIVE_AB_SLICE_FN,
  type IrNativeBufferFn,
} from "../../shared/contracts/native-buffer-adapters.js";
import { allocLocal } from "../context/locals.js";
import type { CodegenContext, FunctionContext } from "../context/types.js";
import { emitArrayBufferSliceParamsBody, i32ByteVec, makeHelperFctx } from "../dataview-native.js";
import { ensureNamedHelperFunc } from "../func-space.js";
import { addFuncType, getOrRegisterResizableAbType } from "../registry/types.js";
import {
  arrayBufferMaxByteLengthInstrs,
  arrayBufferResizableInstrs,
  buildPackedByteLengthElse,
  byteVecLengthInstrs,
  emitArrayBufferAllocFixed,
  emitArrayBufferLengthToIndex,
  emitResizableAbAlloc,
  emitResizableAbLength,
  emitResizableAbMaxLength,
} from "./array-buffer-native.js";

const F64: ValType = { kind: "f64" };
const I32: ValType = { kind: "i32" };
const EXTERNREF: ValType = { kind: "externref" };

/**
 * True when this backend can mint the adapters: a lane with no JS
 * environment at all (standalone, WASI), whose dynamic carrier is externref.
 * The environment is the question, not the IR's provider-regime projection:
 * a JS-environment build projects as standalone there, and its output must
 * stay byte-identical while the JS-host lane is retired.
 */
export function nativeBufferProvidersAvailable(ctx: CodegenContext): boolean {
  const { backend, environment } = ctx.targetProfile;
  return backend === "wasmgc" && (environment === "none" || environment === "wasi") && !ctx.fast;
}

/** Param 0's buffer as an anyref in a fresh local. */
function receiverAnyLocal(fctx: FunctionContext): number {
  const local = allocLocal(fctx, `__ab_any_${fctx.locals.length}`, { kind: "anyref" });
  fctx.body.push({ op: "local.get", index: 0 }, { op: "any.convert_extern" }, { op: "local.set", index: local });
  return local;
}

/** One adapter's signature and body emitter. */
interface AdapterSpec {
  readonly params: readonly ValType[];
  readonly result: ValType;
  emit(ctx: CodegenContext, fctx: FunctionContext): void;
}

const ADAPTERS: Readonly<Record<IrNativeBufferFn, AdapterSpec>> = {
  [IR_NATIVE_AB_NEW_FN]: {
    params: [F64],
    result: EXTERNREF,
    emit(ctx, fctx) {
      const { vecTypeIdx, arrTypeIdx } = i32ByteVec(ctx);
      fctx.body.push({ op: "local.get", index: 0 });
      emitArrayBufferLengthToIndex(ctx, fctx);
      emitArrayBufferAllocFixed(fctx, vecTypeIdx, arrTypeIdx);
      fctx.body.push({ op: "extern.convert_any" });
    },
  },
  [IR_NATIVE_AB_NEW_RESIZABLE_FN]: {
    params: [F64, F64],
    result: EXTERNREF,
    emit(ctx, fctx) {
      const { arrTypeIdx } = i32ByteVec(ctx);
      const rabTypeIdx = getOrRegisterResizableAbType(ctx);
      fctx.body.push({ op: "local.get", index: 0 });
      const lenI32 = emitResizableAbLength(ctx, fctx);
      fctx.body.push({ op: "local.get", index: 1 });
      const maxI32 = emitResizableAbMaxLength(ctx, fctx);
      emitResizableAbAlloc(ctx, fctx, arrTypeIdx, rabTypeIdx, lenI32, maxI32);
      fctx.body.push({ op: "extern.convert_any" });
    },
  },
  [IR_NATIVE_AB_BYTE_LENGTH_FN]: {
    params: [EXTERNREF],
    result: F64,
    emit(ctx, fctx) {
      const { vecTypeIdx } = i32ByteVec(ctx);
      const any = receiverAnyLocal(fctx);
      fctx.body.push(...byteVecLengthInstrs(vecTypeIdx, any, buildPackedByteLengthElse(ctx, any)));
      fctx.body.push({ op: "f64.convert_i32_s" });
    },
  },
  [IR_NATIVE_AB_MAX_BYTE_LENGTH_FN]: {
    params: [EXTERNREF],
    result: F64,
    emit(ctx, fctx) {
      const { vecTypeIdx } = i32ByteVec(ctx);
      const any = receiverAnyLocal(fctx);
      fctx.body.push(...arrayBufferMaxByteLengthInstrs(vecTypeIdx, getOrRegisterResizableAbType(ctx), any));
      fctx.body.push({ op: "f64.convert_i32_u" });
    },
  },
  [IR_NATIVE_AB_RESIZABLE_FN]: {
    params: [EXTERNREF],
    result: I32,
    emit(ctx, fctx) {
      const any = receiverAnyLocal(fctx);
      fctx.body.push(...arrayBufferResizableInstrs(getOrRegisterResizableAbType(ctx), any));
    },
  },
  [IR_NATIVE_AB_SLICE_FN]: {
    params: [EXTERNREF, EXTERNREF, EXTERNREF],
    result: EXTERNREF,
    emit(ctx, fctx) {
      emitArrayBufferSliceParamsBody(ctx, fctx, 0);
    },
  },
};

/** Mint the adapter `symbol`, idempotently, on a lane whose plan certified a call to it. */
export function ensureIrNativeBufferAdapter(ctx: CodegenContext, symbol: IrNativeBufferFn): FuncHandle {
  const spec = ADAPTERS[symbol];
  return ensureNamedHelperFunc(
    ctx,
    symbol,
    () => addFuncType(ctx, [...spec.params], [spec.result]),
    () => {
      const params = spec.params.map((type, index) => ({ name: `p${index}`, type }));
      const fctx = makeHelperFctx(symbol, params, spec.result);
      spec.emit(ctx, fctx);
      return { locals: fctx.locals, body: fctx.body };
    },
  );
}
